with eligible as (select s.* from departments s where not exists (select 1 from employees x where x.dept_id = s.id and x.email not like '%@yahoo.com')) select case when budget >= 3120000 then 'PREMIUM' else 'STANDARD' end as budget_tier, dept_name, stddev_samp(budget) as budget_stddev, count(*) filter (where dept_name = 'Marketing') as marketing_rows from eligible group by budget_tier, dept_name order by budget_tier desc nulls first;
